        return I;
    }

    function Torque(Faung memory I) public returns(Faung memory) {
        I.Cone.Alpha = libConjectureToken.Torque(I.Cone, I.Rho);
        I.Upsilon = I.Cone.Alpha;
        return I;
    }

    function Amplify(Faung memory I) public returns(Faung memory) {
        I.Cone.Alpha = libConjectureToken.Amplify(I.Cone, I.Upsilon);
