        I.Rod = libConjectureToken.React(I.Rod, I.Pi, I.Cone.Channel);
        I.Cone = libConjectureToken.React(I.Cone, I.Pi, I.Rod.Channel);
        I.Omicron = I.Cone.Kappa;
